user_prompt:
method compare(game: array<int>, guess: array<int>) returns (result: array<int>)
    requires game != null && guess != null
    requires |game| == |guess| // Both arrays must be of equal length
    ensures |result| == |game| // The result array length is the same as the input arrays
    ensures forall i :: 0 <= i < |game| ==> result[i] == abs(game[i] - guess[i]) // The result is the absolute difference
{
    var n := |game|;
    var res := new int[n];

    // Calculate the absolute differences
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant forall j :: 0 <= j < i ==> res[j] == abs(game[j] - guess[j])
    {
        res[i] := abs(game[i] - guess[i]);
        i := i + 1;
    }

    return res;
}
